import * as T from './vendor/three.module.js';
export {T};
const mat=(color,extra={})=>new T.MeshStandardMaterial({color,roughness:.77,metalness:.03,...extra});
function mesh(g,m,parent,x=0,y=0,z=0){const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function ball(r,c,parent,x,y,z,detail=20){return mesh(new T.SphereGeometry(r,detail,14),mat(c),parent,x,y,z);}
function box(w,h,d,c,parent,x,y,z){return mesh(new T.BoxGeometry(w,h,d),mat(c),parent,x,y,z);}
function cyl(r1,r2,h,c,parent,x,y,z,n=32){return mesh(new T.CylinderGeometry(r1,r2,h,n),mat(c),parent,x,y,z);}
function ring(r,tube,c,parent,x,y,z){return mesh(new T.TorusGeometry(r,tube,8,64),mat(c,{emissive:c,emissiveIntensity:.25}),parent,x,y,z);}
function roundedShape(w,h,r){const s=new T.Shape(),x=-w/2,y=-h/2;s.moveTo(x+r,y);s.lineTo(x+w-r,y);s.quadraticCurveTo(x+w,y,x+w,y+r);s.lineTo(x+w,y+h-r);s.quadraticCurveTo(x+w,y+h,x+w-r,y+h);s.lineTo(x+r,y+h);s.quadraticCurveTo(x,y+h,x,y+h-r);s.lineTo(x,y+r);s.quadraticCurveTo(x,y,x+r,y);return s;}
function slab(w,d,depth,r,color,parent,y){const o=mesh(new T.ExtrudeGeometry(roundedShape(w,d,r),{depth,bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:.13,bevelThickness:.025,curveSegments:8}),mat(color),parent);o.rotation.x=-Math.PI/2;o.position.y=y-depth;return o;}
function crystal(parent,x,z,scale,color){const g=new T.Group();g.position.set(x,0,z);parent.add(g);for(let i=0;i<3;i++){const h=scale*(i===0?1.65:1),o=mesh(new T.ConeGeometry(scale*.28,h,5),mat(color,{emissive:color,emissiveIntensity:.18,metalness:.15}),g,(i-1)*scale*.35,h/2,(i%2)*.3);o.rotation.z=(i-1)*.18;}return g;}
function mushroom(parent,x,z,s){const g=new T.Group();g.position.set(x,0,z);parent.add(g);cyl(.09*s,.17*s,.8*s,0xb8cacf,g,0,.4*s,0);const head=ball(.5*s,0xb99ee7,g,0,.85*s,0);head.scale.y=.4;ring(.47*s,.025*s,0xdac5ff,g,0,.86*s,0).rotation.x=Math.PI/2;return g;}
