 const universe=new T.Group();scene.add(universe);const particles=[];for(let i=0;i<420;i++){const sx=(Math.random()-.5)*80,sy=(Math.random()-.5)*60,depth=40+Math.random()*15;particles.push(.814*sx-.37*sy-.45*depth,.77*sy-.64*depth,-.58*sx-.52*sy-.62*depth);}const sg=new T.BufferGeometry();sg.setAttribute('position',new T.Float32BufferAttribute(particles,3));const starfield=new T.Points(sg,new T.PointsMaterial({color:0xe8dbff,size:.19,sizeAttenuation:true,transparent:true,opacity:.75}));universe.add(starfield);
