 const asteroids=[];for(let i=0;i<21;i++){let a=i*2.399,rad=17+(i%4)*5;const o=mesh(new T.DodecahedronGeometry(.3+(i%4)*.25,0),mat(i%2?0x7b6999:0x6a647e),universe,Math.cos(a)*rad,-3-(i%3)*2,Math.sin(a)*rad);o.rotation.set(i,i*2,i*.4);asteroids.push(o);}
 const trail=[],fx=[],course=new T.Group();scene.add(course);const ballMesh=ball(.23,0xfff6e5,scene,0,.23,8);ballMesh.material.roughness=.28;ballMesh.material.emissive=new T.Color(0xffe7b0);ballMesh.material.emissiveIntensity=.2;const shadow=mesh(new T.CircleGeometry(.35,24),new T.MeshBasicMaterial({color:0x18322a,transparent:true,opacity:.28,depthWrite:false}),scene);shadow.rotation.x=-Math.PI/2;shadow.position.y=.025;
