 const world={renderer,scene,camera,course,ballMesh,shadow,pup,aim,aimDots,cursor,stars:[],portals:[],bumpers:[],fx,trail,saturn,starfield,asteroids,cameraAngle:innerWidth<550?.18:.62,topView:false,desiredAngle:innerWidth<550?.18:.62};
