 for(let i=0;i<18;i++){const a=i/18*Math.PI*2,x=Math.cos(a)*6.5,z=Math.sin(a)*10.4;const o=mesh(new T.DodecahedronGeometry(.75+(i%3)*.25,0),mat(i%2?0x675c7a:0x82718e),g,x,-1.5,z);o.scale.y=1.5;o.rotation.set(i,.2*i,.4);}
 crystal(g,-6,-9.4,.8,0xb396ed);crystal(g,5.9,8.7,.65,0x8ce7d5);crystal(g,6.2,-9.3,.85,0xb79bf2);mushroom(g,-6.3,7.6,.8);mushroom(g,-5.6,8.4,.55);mushroom(g,6.1,2.8,.6);
 // Tee markings.
 for(const x of [-.65,.65])cyl(.075,.075,.13,0xf3eee2,g,c.start[0]+x,.19,c.start[1]);const tee=ring(.52,.015,0xe6f0cd,g,c.start[0],.13,c.start[1]);tee.rotation.x=Math.PI/2;
 const hole=cyl(.51,.46,.09,0x17282a,g,c.hole[0],.13,c.hole[1]);hole.material=new T.MeshBasicMaterial({color:0x18272b});ring(.51,.035,0xd8e8c7,g,c.hole[0],.185,c.hole[1]).rotation.x=Math.PI/2;const pole=cyl(.033,.038,2.5,0xf3ece1,g,c.hole[0],1.4,c.hole[1]);const flagShape=new T.Shape();flagShape.moveTo(0,0);flagShape.lineTo(1.1,-.2);flagShape.lineTo(0,-.6);flagShape.closePath();const flag=mesh(new T.ShapeGeometry(flagShape),new T.MeshStandardMaterial({color:0xdf91b4,side:T.DoubleSide,roughness:1}),g,c.hole[0],2.64,c.hole[1]);flag.rotation.y=-.3;ball(.065,0xf6dbb0,g,c.hole[0],2.68,c.hole[1]);w.flag=flag;
 for(const r of c.walls){box(r.w,r.h,r.d,0xaca1c3,g,r.x,r.h/2+.1,r.z);box(r.w,.06,r.d+.08,0xe0d9e6,g,r.x,r.h+.13,r.z);for(let x=-r.w/2+.4;x<r.w/2;x+=.7)box(.25,.06,r.d+.1,0x9c89b5,g,r.x+x,r.h+.17,r.z);}
 for(const r of c.sand){const patch=box(r.w,.028,r.d,0xd6b880,g,r.x,.13,r.z);patch.castShadow=false;for(let i=0;i<35;i++){const s=ball(.025,0xa99162,g,r.x+(Math.random()-.5)*r.w,.154,r.z+(Math.random()-.5)*r.d,5);s.scale.y=.25;}}
 for(const r of c.bumpers){const b=new T.Group();b.position.set(r.x,0,r.z);g.add(b);cyl(r.r,r.r,.65,r.moving?0x8773b0:0xb9a2cd,b,0,.48,0);cyl(r.r+.09,r.r+.09,.15,0xe8d5ed,b,0,.83,0);const top=ball(r.r*.78,r.moving?0xe8a7c4:0xc9a9de,b,0,.91,0);top.scale.y=.45;ring(r.r+.02,.07,r.moving?0xf6bcce:0xbbe9ac,b,0,.38,0).rotation.x=Math.PI/2;if(r.moving){for(const x of [-.23,.23])ball(.085,0x34304b,b,x,1.06,.57);}w.bumpers.push({mesh:b,config:r});}
