 for(const p of c.jumps){box(p.w,.11,p.d,0x9a78bd,g,p.x,.17,p.z);for(let i=-1;i<=1;i++)box(.09,.02,p.d*.7,0xe7c7ff,g,p.x+i*.55,.24,p.z);}
